use mdbook_language_lab::process;
use serde_json::{Value, json};

fn chapter(path: &str, content: &str) -> Value {
    json!({"Chapter": {"path": path, "content": content, "sub_items": []}})
}
fn render(source: &str) -> String {
    let mut book = json!({"items": [chapter("test.md", source)]});
    process(&mut book).unwrap();
    book["items"][0]["Chapter"]["content"]
        .as_str()
        .unwrap()
        .into()
}

// Let the Markdown parser identify inline code, so fenced/indented examples and
// literal code spans are never mistaken for roles. Preserve all other source bytes.
pub fn roles(source: &str) -> Vec<Role> {
    let mut result = Vec::new();
    let mut nested_link = 0;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(Tag::Link { .. } | Tag::Image { .. }) => nested_link += 1,
            Event::End(TagEnd::Link | TagEnd::Image) => nested_link -= 1,
            Event::Code(label) if nested_link == 0 => {
                let prefix = &source[..range.start];
                if !prefix.ends_with('}') {
                    continue;
                }
                let Some(start) = prefix.rfind('{') else {
                    continue;
                };
                let escapes = prefix[..start]
                    .bytes()
                    .rev()
                    .take_while(|b| *b == b'\\')
                    .count();
                if escapes % 2 != 0 {
                    continue;
                }
                let name = &prefix[start + 1..prefix.len() - 1];
                if name == "req" || (valid_id(name) && name.contains('.')) {
                    result.push(Role {
                        range: start..range.end,
                        name: name.into(),
                        label: label.into_string(),
                    });
                }
            }
            _ => {}
        }
    }
    result
}

    chapters(items, &mut |ch| {
        let source = ch["content"].as_str().ok_or("missing chapter content")?;
        let mut output = source.to_owned();
        for role in roles(source).into_iter().rev() {
            let path = ch["path"]
                .as_str()
                .ok_or("role in chapter without output path")?;
            let definition = role.name == "req";
            let id = if definition { &role.label } else { &role.name };
            let target = definitions
                .get(id)
                .ok_or_else(|| format!("{path}: unknown requirement {id}"))?;
            let html = if definition {
                format!(
                    "<a class=\"requirement-badge\" id=\"req-{id}\" href=\"#req-{id}\" aria-label=\"Requirement {id}\"><span class=\"requirement-kind\">REQ</span><span class=\"requirement-name\">{id}</span></a>"
                )
            } else {
                format!(
                    "<a class=\"requirement-reference\" href=\"{}\" title=\"Requirement {id}\">{}</a>",
                    escape(&href(path, target, id)),
                    escape(&role.label)
                )
            };
            output.replace_range(role.range, &html);
        }
        ch["content"] = output.into();
        Ok(())
    })
}

#[test]
fn literal_markdown_contexts_remain_byte_identical() {
    let cases = [
        "```markdown\n{req}`fake.id`\n{missing.id}`reference`\n```\n",
        "~~~\n{req}`fake.id`\n~~~\n",
        "    {req}`fake.id`\n\n    {missing.id}`reference`\n",
        "``{req}`fake.id` `` and ``{missing.id}`reference` ``\n",
        "\\{req}`fake.id` and \\{missing.id}`reference`\n",
        "[{req}`fake.id`](https://example.com)\n",
        "![{req}`fake.id`](image.png)\n",
        "[{missing.id}`reference`][target]\n\n[target]: page.md\n",
        "![{missing.id}`reference`][image]\n\n[image]: image.png\n",
    ];
    for source in cases {
        assert_eq!(render(source), source);
    }
    // An even number of backslashes escapes the slash, not the role brace.
    assert!(render("\\\\{req}`real.id`").starts_with("\\\\<a "));
}

#[test]
fn html_labels_escape_all_special_characters() {
    let output = render("{req}`a.b` Text.\n\n{a.b}`<img src=x onerror='bad' title=\"bad\"> &`");
    assert!(
        output.contains("&lt;img src=x onerror=&#39;bad&#39; title=&quot;bad&quot;&gt; &amp;</a>")
    );
    assert!(!output.contains("<img"));
}

#[test]
fn preserves_bytes_outside_roles_including_unicode_and_crlf() {
    let prefix = "# Ελληνικά\r\n\r\n  **Before**\t";
    let suffix = "\tAfter  \r\n\r\n[link](target)\r\n{note}`untouched`\r\n";
    let badge = render("{req}`a.b`");
    assert_eq!(
        render(&format!("{prefix}{{req}}`a.b`{suffix}")),
        format!("{prefix}{badge}{suffix}")
    );
    assert_eq!(
        render("No roles\r\nUnicode: πήγα 🦀\n"),
        "No roles\r\nUnicode: πήγα 🦀\n"
    );
}
